UPDATE abnormal_records
mold_id = #{moldId}, abnormal_type = #{abnormalType}, measured_value = #{measuredValue}, threshold_value = #{thresholdValue}, description = #{description}, occurred_at = #{occurredAt}, source_type = #{sourceType}, operator_id = #{operatorId}, device_id = #{deviceId}, linked_repair_id = #{linkedRepairId}, linked_log_id = #{linkedLogId},
WHERE id = #{id}

mapper.select:
SELECT a.id, a.mold_id, m.mold_code, m.name AS mold_name, a.abnormal_type, a.measured_value, a.threshold_value, a.description, a.occurred_at, a.source_type, a.operator_id, u.real_name AS operator_name, a.created_at FROM abnormal_records a LEFT JOIN molds m ON a.mold_id = m.id LEFT JOIN users u ON a.operator_id = u.id
AND a.mold_id = #{moldId}
AND ( m.name LIKE CONCAT('%', #{keyword}, '%') OR m.mold_code LIKE CONCAT('%', #{keyword}, '%') )
AND a.abnormal_type = #{abnormalType}
AND a.operator_id = #{operatorId}
AND a.source_type = #{sourceType}
AND a.occurred_at >= #{startTime}
AND a.occurred_at <= #{endTime}
ORDER BY a.occurred_at DESC, a.created_at DESC

SELECT mold_id FROM abnormal_records
WHERE occurred_at >= #{since}
GROUP BY mold_id
HAVING COUNT(1) >= #{threshold}
